import{_ as a,H as i,f as e,i as n}from"./chunks/framework.BH2BK_3i.js";const k=JSON.parse('{"title":"12 | 上下文窗口：怎么设计一个动态编排的Context策略？","description":"","frontmatter":{},"headers":[{"level":2,"title":"Prompt Prefix Cache","slug":"prompt-prefix-cache","link":"#prompt-prefix-cache","children":[]},{"level":2,"title":"基础方案","slug":"基础方案","link":"#基础方案","children":[{"level":3,"title":"筛选 Select：当前步骤到底需要什么 Context","slug":"筛选-select-当前步骤到底需要什么-context","link":"#筛选-select-当前步骤到底需要什么-context","children":[]},{"level":3,"title":"强规则筛选","slug":"强规则筛选","link":"#强规则筛选","children":[]},{"level":3,"title":"检索召回","slug":"检索召回","link":"#检索召回","children":[]},{"level":3,"title":"大模型筛选","slug":"大模型筛选","link":"#大模型筛选","children":[]},{"level":3,"title":"压缩 Cmpress","slug":"压缩-cmpress","link":"#压缩-cmpress","children":[]},{"level":3,"title":"排序","slug":"排序","link":"#排序","children":[]}]},{"level":2,"title":"高级方案：基于剩余窗口大小调整 Context 内容","slug":"高级方案-基于剩余窗口大小调整-context-内容","link":"#高级方案-基于剩余窗口大小调整-context-内容","children":[{"level":3,"title":"本质：预算分配问题","slug":"本质-预算分配问题","link":"#本质-预算分配问题","children":[]},{"level":3,"title":"第一层：必须原样放入的内容","slug":"第一层-必须原样放入的内容","link":"#第一层-必须原样放入的内容","children":[]},{"level":3,"title":"第二层：根据窗口大小决定是否压缩的 Context","slug":"第二层-根据窗口大小决定是否压缩的-context","link":"#第二层-根据窗口大小决定是否压缩的-context","children":[]},{"level":3,"title":"可以放入动态策略的更多因素","slug":"可以放入动态策略的更多因素","link":"#可以放入动态策略的更多因素","children":[]},{"level":3,"title":"动态编排决策表（供参考）","slug":"动态编排决策表-供参考","link":"#动态编排决策表-供参考","children":[]}]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"AIAgent系统设计面试现场/12｜上下文窗口：怎么设计一个动态编排的Context策略？.md","filePath":"AIAgent系统设计面试现场/12｜上下文窗口：怎么设计一个动态编排的Context策略？.md","lastUpdated":1795451227000}'),t={name:"AIAgent系统设计面试现场/12｜上下文窗口：怎么设计一个动态编排的Context策略？.md"};function p(l,s,h,o,r,c){return i(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="_12-上下文窗口-怎么设计一个动态编排的context策略" tabindex="-1">12 | 上下文窗口：怎么设计一个动态编排的Context策略？ <a class="header-anchor" href="#_12-上下文窗口-怎么设计一个动态编排的context策略" aria-label="Permalink to &quot;12 | 上下文窗口：怎么设计一个动态编排的Context策略？&quot;">​</a></h1><p>你好，我是大明，今天我们继续讨论 Context 和 Context Window。</p><p>上一讲我们只是构建了一个基本的 Context 的抽象，讨论了滑动窗口算法，并且进一步讨论了怎么对 Context 进行分层。</p><p>这一讲我们要进一步深入讨论 f 的具体算法，也就是讨论什么东西应该放进大模型窗口，传递给大模型；哪些不需要。</p><p>在这些内容的基础上，我会引入一个动态编排的机制，它会给你塑造一个基本的框架，允许你参考这个框架设计不同的窗口编排算法。面试中用起来效果极佳，不可错过。下面我们先来学习一点基础知识。</p><h2 id="prompt-prefix-cache" tabindex="-1">Prompt Prefix Cache <a class="header-anchor" href="#prompt-prefix-cache" aria-label="Permalink to &quot;Prompt Prefix Cache&quot;">​</a></h2><p>这是大模型里面的一个赫赫有名的机制，叫做 Prefix Cache。</p><p>你可以直接类比到 SQL 层面上的前缀索引。也就是说，如果你的 Prompt 的前缀部分是一样的，那么它就可以利用之前推理的缓存，快速推理下去。相当于这部分相同的内容就不需要从0 开始推理了。</p><p>下图是一个不太严谨的示例，但是能够帮助你理解。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AIAgent%E7%B3%BB%E7%BB%9F%E8%AE%BE%E8%AE%A1%E9%9D%A2%E8%AF%95%E7%8E%B0%E5%9C%BA/images/12/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AIAgent%E7%B3%BB%E7%BB%9F%E8%AE%BE%E8%AE%A1%E9%9D%A2%E8%AF%95%E7%8E%B0%E5%9C%BA/images/12/1.png" alt=""></a></p><h2 id="基础方案" tabindex="-1">基础方案 <a class="header-anchor" href="#基础方案" aria-label="Permalink to &quot;基础方案&quot;">​</a></h2><p>这个基础方案，有一个很不错的名字，叫做 Context Compiler。这个方案不是单纯拼Prompt，而是带有明显的工程化意味，而且 Compiler 这个词一听就非常高级。</p><p>整体抽象可以看作是这样：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Window_t </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Inject(</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Order(</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   Compress</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">     Select</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(AllContext_t),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   )</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> )</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>而后，你可以将 AllContext_t 扩展一下，也就是引入额外两个参数，看起来会更加清晰：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Window_t </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Inject(</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Order(</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   Compress</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">     Select</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(AllContext_t, TaskState_t),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">     TokenBudget_t</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   )</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> )</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><ul><li><p>AllContext_t 是当前系统里所有可用的 Context，包括用户输入、历史对话、用户画像、工具结果、检索结果、任务状态、Plan 状态、约束等等。</p></li><li><p>TaskState_t 是当前任务状态，也就是当前 Agent 正在做什么，处于哪一个步骤，目标是什么，已经执行到哪里，还缺什么。</p></li><li><p>TokenBudget_t 是当前可用的 Token 预算。</p></li></ul><p>最终得到的 Window_t，才是真正传给大模型的上下文窗口。</p><p>换句话来说，上下文窗口是上下文经过选择（Select）、压缩（Compress）、排序（Order）、注入（Inject）得到的产物。</p><h3 id="筛选-select-当前步骤到底需要什么-context" tabindex="-1">筛选 Select：当前步骤到底需要什么 Context <a class="header-anchor" href="#筛选-select-当前步骤到底需要什么-context" aria-label="Permalink to &quot;筛选 Select：当前步骤到底需要什么 Context&quot;">​</a></h3><p>筛选也是讲究技巧的，最直接的想法就是站在整个任务的角度来选上下文。</p><p>比如说在商品推荐的时候，用户说“帮我推荐一个 8000 块的电脑”。那么很自然的想法就是将用户画像、预算、商品库、笔记本参数、品牌偏好、历史购买记录、评价数据等一股脑放入窗口里面，传递给大模型。</p><p>这种想法有没有效果呢？那肯定是有效果的，但是只有一点点。</p><p>一方面是大模型得自己去决定哪些信息能用、哪些信息不能用；另外一方面，不同的步骤需要的内容其实是不同的，全部丢过去也浪费 token，还影响大模型效果。</p><p>核心在于，每个阶段、每个步骤需要的内容不同。因此筛选的关键就是在一大堆的上下文里面找出当前这一次调用大模型真正需要的内容，所谓“弱水三千，只取一瓢”。</p><p>主流的筛选机制有三种，强规则筛选、检索召回和模型筛选，你可以独立使用也可以混合使用。</p><h3 id="强规则筛选" tabindex="-1">强规则筛选 <a class="header-anchor" href="#强规则筛选" aria-label="Permalink to &quot;强规则筛选&quot;">​</a></h3><p>也就是在 Prompt 模板、代码层面上就直接能决定放入什么不放入什么。当然，你也可以考虑使用一些规则引擎之类的机制，比如说符合某个条件的大模型调用就需要带上什么内容，又或者借助标签之类的机制。</p><p>这里我简单解释一下 Prompt 模板是怎么运作的。它的原理非常简单，就是在写 Prompt 的时候，里面留下一些占位符，这些占位符就对应了 Context 里面的一些内容。过程类似于：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AIAgent%E7%B3%BB%E7%BB%9F%E8%AE%BE%E8%AE%A1%E9%9D%A2%E8%AF%95%E7%8E%B0%E5%9C%BA/images/12/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AIAgent%E7%B3%BB%E7%BB%9F%E8%AE%BE%E8%AE%A1%E9%9D%A2%E8%AF%95%E7%8E%B0%E5%9C%BA/images/12/2.png" alt=""></a></p><p>比如说我以前用 Go 来渲染 Prompt 的时候，写出来的模板就类似这样：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 用户画像</span></span>
<span class="line"><span>{​{ .UserProfile}​}</span></span>
<span class="line"><span># 用户输入</span></span>
<span class="line"><span>{​{ .Input }​}</span></span></code></pre></div><p>它有一个隐含的前提，就是当真正发起调用的时候，Context 里面一定有 UserProfile 和Input 两个字段。至于 Context 是怎么获得这些字段的，它可以是前面步骤工具调用之后被放入到 Context 里面的，也可以完全不关心是哪里来的。</p><p>另外一个需要解释的就是代码直接写死大模型调用需要的各种上下文内容。这也是我非常喜欢的一种做法，它在处理复杂的大模型调用上有非常大的优势。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AIAgent%E7%B3%BB%E7%BB%9F%E8%AE%BE%E8%AE%A1%E9%9D%A2%E8%AF%95%E7%8E%B0%E5%9C%BA/images/12/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AIAgent%E7%B3%BB%E7%BB%9F%E8%AE%BE%E8%AE%A1%E9%9D%A2%E8%AF%95%E7%8E%B0%E5%9C%BA/images/12/3.png" alt=""></a></p><p>如上图的 AbcLLMAction 就是对 LLMAction 的二次封装，在 Java 里面可以表现为继承，在Go 里面可以表现为组合，也可以用装饰器这个设计模式来实现。</p><p>AbcLLMAction 它的内部代码会自己决定从 Context 里面获取哪些字段，而且怎么放进Prompt 里面，伪代码：</p><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">a </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">AbcLLMAction</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">buildPrompt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ctx</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> agent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Context</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">args</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">...</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">any</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   res </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;我要开始拼接 Prompt 了&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   val1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ctx.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Get</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;key1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   res </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;xxx&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> val1</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   // ...</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">   return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> res</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>这种做法在实践中很好用，唯独在面试中不太好用。</p><h3 id="检索召回" tabindex="-1">检索召回 <a class="header-anchor" href="#检索召回" aria-label="Permalink to &quot;检索召回&quot;">​</a></h3><p>检索召回非常好理解，就是根据当前要发起大模型调用的目标，去向量数据库、ES、甚至于数据库等存储里面找到相关的内容，放入到 Prompt 中。</p><p>检索召回可以参考 RAG 机制，也同样有查找、过滤、重排序等问题。</p><h3 id="大模型筛选" tabindex="-1">大模型筛选 <a class="header-anchor" href="#大模型筛选" aria-label="Permalink to &quot;大模型筛选&quot;">​</a></h3><p>它的基本思路就是在真的发起调用之前，先调用一次大模型，看看需要什么 Context 的内容。而后再发起真正的大模型调用。这两次之间的大模型可以是同一个，也可以是不同的大模型。比如说第一次大模型调用我倾向于使用 flash、mini 之类的大模型，快速返回结果。</p><p>整个过程如图：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AIAgent%E7%B3%BB%E7%BB%9F%E8%AE%BE%E8%AE%A1%E9%9D%A2%E8%AF%95%E7%8E%B0%E5%9C%BA/images/12/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AIAgent%E7%B3%BB%E7%BB%9F%E8%AE%BE%E8%AE%A1%E9%9D%A2%E8%AF%95%E7%8E%B0%E5%9C%BA/images/12/4.png" alt=""></a></p><p>总的来说，这种做法不太常见，因为两次大模型调用成本高、性能差。</p><h3 id="压缩-cmpress" tabindex="-1">压缩 Cmpress <a class="header-anchor" href="#压缩-cmpress" aria-label="Permalink to &quot;压缩 Cmpress&quot;">​</a></h3><p>有些时候，如果你筛选的内容比较少，那么可以全部放入到窗口内。但是大部分时候，你的窗口总是不够用的。所以你需要考虑的就是压缩，将一段长的内容压缩成一段短的内容。</p><p>这个过程中要考虑的问题是：</p><ul><li><p>选出来的这些内容，哪些需要压缩？</p></li><li><p>压缩的时候，压缩到什么地步？</p></li></ul><p>我认为是否压缩取决于 Context 内容的重要性和剩余窗口大小。整体原则就是：越重要的内容越不能压缩，即便真要压缩，那么压缩程度也应该尽可能低；剩余窗口越大，越不需要压缩。当剩余窗口变小之后，压缩的程度可以升高。</p><p>如图：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AIAgent%E7%B3%BB%E7%BB%9F%E8%AE%BE%E8%AE%A1%E9%9D%A2%E8%AF%95%E7%8E%B0%E5%9C%BA/images/12/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AIAgent%E7%B3%BB%E7%BB%9F%E8%AE%BE%E8%AE%A1%E9%9D%A2%E8%AF%95%E7%8E%B0%E5%9C%BA/images/12/5.png" alt=""></a></p><p>也就是说，压缩它不是一个静态、固定的机制，每次需要压缩的时候就调用一下。而是说，要根据实时情况来决定压缩策略。</p><p>更进一步，即便是同一个内容，同样的重要程度和同样的剩余窗口大小，但是因为调用大模型的目标有差异，也可以采用不同的压缩策略。</p><p>比如在决定压缩用户画像的时候，如果此时是在商品推荐任务中，那么只能简单压缩一下；而如果是在售后服务中，就可以极度压缩一下，毕竟你退款退货跟你的用户画像就没啥关系了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AIAgent%E7%B3%BB%E7%BB%9F%E8%AE%BE%E8%AE%A1%E9%9D%A2%E8%AF%95%E7%8E%B0%E5%9C%BA/images/12/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AIAgent%E7%B3%BB%E7%BB%9F%E8%AE%BE%E8%AE%A1%E9%9D%A2%E8%AF%95%E7%8E%B0%E5%9C%BA/images/12/6.png" alt=""></a></p><p>另外一种做法是在 Context 里面直接保留多个不同的压缩版本，在不同的场景下直接使用，而不是每次要用的时候再去压缩。下面是一个例子：</p><ul><li><p>L0：一句话摘要</p></li><li><p>L1：关键结论摘要</p></li><li><p>L2：结构化事实</p></li><li><p>L3：详细摘要</p></li><li><p>L4：完整原文</p></li></ul><p>这种动态压缩策略的关键点在于为同一份信息准备多个精度版本，按需加载。而且因为提前压缩好了，所以在运行过程中没有任何的额外压缩的开销。</p><p>当然在面试中你可以随便搞几个层级，讲述你的压缩策略、压缩层级。</p><h3 id="排序" tabindex="-1">排序 <a class="header-anchor" href="#排序" aria-label="Permalink to &quot;排序&quot;">​</a></h3><p>首先要明确一点，大模型现在还处于一种“炼丹”状态。也就是同样的内容，排序不同，大模型回复的内容也会不同。</p><p>通常来说，越是重要的内容越是要靠前。比如一种常见的错误就是没有从用户输入中提取出硬约束，结合用户输入在整体输入中的排序比较靠后，导致用户输入中的约束被淹没在别的内容中。</p><p>这里我给出一个参考排序，针对的是之前的内容里面讨论过的各种 Context 内容。仅作为参考，出问题了记得调整顺序。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. System / Spec</span></span>
<span class="line"><span>2. 当前 Goal</span></span>
<span class="line"><span>3. 硬约束</span></span>
<span class="line"><span>4. 当前任务状态 / Plan 节点</span></span>
<span class="line"><span>5. 已确认关键事实</span></span>
<span class="line"><span>6. 当前步骤需要的 Evidence</span></span>
<span class="line"><span>7. 工具 Observation</span></span>
<span class="line"><span>8. 候选 Action / Tool</span></span>
<span class="line"><span>9. 动态 few-shot</span></span>
<span class="line"><span>10. 历史摘要</span></span>
<span class="line"><span>11. 补充背景</span></span></code></pre></div><p>这个顺序的设计原则是，越重要的内容越往前放。如果你对这些内容的重要性认知和我不同，那么可以考虑调整顺序。</p><p>此外上面的这个顺序对缓存不是很友好。比如说已确认的关键事实其实修改的时候并不多，所以可以考虑放到 3 后面，这样可以更好地命中缓存。</p><p>这也是在考虑顺序的另外一个关键因素：缓存，或者说 Prompt Cache/Prefix Cache，你已经在前面的基础知识里面看过了。</p><h2 id="高级方案-基于剩余窗口大小调整-context-内容" tabindex="-1">高级方案：基于剩余窗口大小调整 Context 内容 <a class="header-anchor" href="#高级方案-基于剩余窗口大小调整-context-内容" aria-label="Permalink to &quot;高级方案：基于剩余窗口大小调整 Context 内容&quot;">​</a></h2><p>刚刚我们讨论了上下文的筛选、压缩和排序了。但如果你真的做过复杂 Agent，你会发现有一个问题更加棘手：窗口永远不够用。</p><p>这时候你可能会疑问，百万窗口都不够用吗？</p><p>在复杂 Agent 里面，还真不够用。而且你忽略了一点，你不是每时每刻用的都是百万窗口的大模型。</p><p>所以你会面临窗口不够用的问题，这个时候你的窗口大小管理就不能太死板了。我更加推荐一种高端的管理方式：根据剩余上下文窗口大小，动态决定哪些 Context 原样放入，哪些Context 压缩后放入，哪些 Context 只放索引，哪些 Context 暂时不放，等需要的时候再召回。</p><h3 id="本质-预算分配问题" tabindex="-1">本质：预算分配问题 <a class="header-anchor" href="#本质-预算分配问题" aria-label="Permalink to &quot;本质：预算分配问题&quot;">​</a></h3><p>你可以把上下文窗口看成一个预算池。假设当前模型最多支持 32K Token，系统提示词、输出预留、工具参数等已经占了一部分，那么真正能用于放 Context 的空间可能只有 20K。</p><p>你现在就不能把所有相关的内容都放进去，因为塞不下，所以这里你要问自己一个问题：</p><ul><li><p>哪些内容必须原样放？</p></li><li><p>哪些内容可以结构化压缩？</p></li><li><p>哪些内容只放摘要？</p></li><li><p>哪些内容只放索引？</p></li><li><p>哪些内容完全不放？</p></li><li><p>哪些内容要等模型发现缺失后再检索？</p></li></ul><h3 id="第一层-必须原样放入的内容" tabindex="-1">第一层：必须原样放入的内容 <a class="header-anchor" href="#第一层-必须原样放入的内容" aria-label="Permalink to &quot;第一层：必须原样放入的内容&quot;">​</a></h3><p>不管剩余窗口有多小，有些内容都应该尽量原样保留。这一类 Context 内容的特点是：一旦被压缩、改写、遗漏，就可能导致严重错误。</p><p>比如说最典型的最新用户输入。当然在上下文空间足够的时候，不管是不是最新的用户输入，我都建议你原样保留。只有窗口不够，或者用户输入的内容太长，才需要考虑压缩等。</p><p>除此以外，还有硬约束、已确定关键事实、Plan 和 Plan 执行状态这些都要原样放。你在实践中可以根据自己 Agent 相对应的业务特点来进一步决定什么东西一定要原样放。</p><p>注意，你不需要在 Agent 设计之初就明确什么必须原样不懂，而是可以在迭代的过程中动态决定。</p><h3 id="第二层-根据窗口大小决定是否压缩的-context" tabindex="-1">第二层：根据窗口大小决定是否压缩的 Context <a class="header-anchor" href="#第二层-根据窗口大小决定是否压缩的-context" aria-label="Permalink to &quot;第二层：根据窗口大小决定是否压缩的 Context&quot;">​</a></h3><p>有些 Context 内容是可以压缩的，你可以根据剩余窗口大小决定如何压缩。</p><p>上一讲我讲过一种分层策略，你可以看一下我列出的表格：</p><p>层级</p><ul><li>主要内容（举例）信息形态</li></ul><p>原始层</p><ul><li>完整用户输入、完整对话消息保存完整原始内容</li></ul><p>结构化事实层</p><ul><li>取决于你的结构设计从原始内容中抽取稳定事实</li></ul><p>摘要层</p><ul><li><p>取决于你如何生成摘要摘要用于保留整体语义和过程</p></li><li><p>索引层不保存具体内容，只保存“去哪</p></li></ul><p>索引层</p><ul><li>取决于你如何设计索引，比如哈希结构义是降低常驻 Context 的体积</li></ul><p>对于同一个 Context Item 来说，你可以考虑根据剩余窗口大小来决定放它的什么内容，下面是一个例子：</p><ul><li><p>L0：不放，一般是窗口几乎都放满了，只能是不放了。</p></li><li><p>L1：只放一句话摘要，窗口差不多满了，还能放一点点内容。比如说你可以在剩余窗口大小在 (0%, 10%) 的时候使用这个策略。</p></li><li><p>L2：放结构化摘要，窗口也是比较满了，比如说剩余窗口大小 [10%, 30%)。</p></li><li><p>L3：放详细摘要，窗口放了一些内容，但是剩余窗口还挺大的，比如说 [30%, 50%)</p></li><li><p>L4：放原文 / 完整结果，剩余窗口还剩下非常多，比如说[50%, 100%]</p></li></ul><p>我在这里给出的这种百分比是一种非常简单的策略，你在实践中可以灵活使用。</p><p>我举一些比较复杂的级联的例子，也就是 Context Item 之间是有关系的，并不完全独立。</p><ul><li><p>有两个 Context Item 是强相关的，信息有很强的互补性，那么两者最好保持在同一个压缩级别。</p></li><li><p>有两个 Context Item 的信息有一定的重合，或者说大模型用了 A 就可以不用 B 的信息，那么你可以考虑一个极度压缩，但是另外一个则尽量保持原文。</p></li></ul><p>此外还有一个兜底的机制，就是在你的大模型调用的 Prompt 里面针对压缩内容增加一个兜底条款，下面是一个示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>... Prompt 的一部分</span></span>
<span class="line"><span>xxx（L2）</span></span>
<span class="line"><span>... Prompt 的其它部分</span></span></code></pre></div><ul><li>如果你发现某个内容的压缩程度太高，可以召回更加详细的内容</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>... Prompt 的另外一部分</span></span></code></pre></div><p>对应的你就要提供一个召回细节的 Action。并且你要注意，如果你的窗口真的已经满了，那么召回细节也没用，因为放不进去了。</p><p>你可以在前面的 L0-L4 的基础上，引出一个更加通用的设计，可以称之为动态压缩的档位设计。下面的百分数是指剩余窗口大小：</p><ul><li><p>窗口非常充足：Full Mode，比如说剩余窗口大小 [80%, 100%]。</p></li><li><p>窗口中等：Balanced Mode，大部分情况下你应该控制你的 Agent 在这个阶段运行。这个阶段可以控制在 [20%, 80%) 之间。</p></li><li><p>窗口紧张：Compact Mode，Agent 可以短时间进入这个状态，但是应该尽可能退出，比如说对 Context Item 之类的进行一些淘汰、压缩等。这个阶段可以控制在 [5%, 20%)。</p></li><li><p>窗口极度紧张：Minimal Mode，基本上你可以认为窗口即将占满，此时你的 Agent 只能勉强维持运行，应该尽快考虑解决窗口紧张的问题。这个阶段基本上就是 [0, 5%）了。</p></li></ul><p>我这个设计你可以作为参考，而后各个阶段的英文名也可以用在面试中，会显得非常高级。</p><p>而如果你胆大心细，那么你可以设计自己的档位，比如说增加、减少档位，或者调整每个档位的阈值。面试话术参考：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我设计了一个基于剩余窗口大小动态算法。在这个算法里面，我根据剩余窗口的大小分成了 N 档。</span></span>
<span class="line"><span>第一档是 Full Mode，窗口非常充足。在这个状态下，基本不需要压缩，都是原文直接放置。</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>第 X 档是 Partial Compact Mode（这是我随便编的），顾名思义在这个阶段部分 Context Item 会被压</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>第 Y 档是 Minimal Mode，除了必须要保持原文的 A、B、C 这些字段，其余全部都被压缩，并且压缩的程</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>整个算法，就我观察来说，大于 80% 的时间是运行在 Balanced Mode（最好选这个作为长时间运行的 mod</span></span>
<span class="line"><span>而且我们对 Minimal Mode 有一个额外的监控，进入这个状态被认为是一种不健康的状态。</span></span></code></pre></div><p>当你制定面试方案的时候，还可以考虑为 Context Item 在不同的 Mode 下，设计压缩算法。实践中我就不太建议专门为一些特殊的 Context Item 设计压缩算法，但是面试用起来效果很好。</p><h3 id="可以放入动态策略的更多因素" tabindex="-1">可以放入动态策略的更多因素 <a class="header-anchor" href="#可以放入动态策略的更多因素" aria-label="Permalink to &quot;可以放入动态策略的更多因素&quot;">​</a></h3><p>前面讨论的都是剩余窗口大小，但是你可以进一步结合其余因素，其中有一部分因素之前我们已经讨论过了。</p><ul><li><p>当前步骤：不同步骤所需的 Context Item 是不同的，需要的程度也是不同的；</p></li><li><p>任务风险等级：高风险任务和低风险任务的上下文策略显然不一样，甚至高风险任务就应该尽量使用大窗口的模型，避免压缩之类的信息损耗引发问题。</p></li><li><p>信息可恢复性：有些信息现在不放，后面还能找回来；有些信息一旦不放，后面就很难恢复。你可以理解为，有些东西可以只放一个索引，后续可以利用索引召回细节。有一些是你不放原文，后面不好召回细节。比如说部分工具的输出结果并没有同步到数据库中，你想召回都没法召回。</p></li><li><p>信息可信度：比如说用户明确确认 &gt; 权威工具结果 &gt; 原始文档 &gt; 历史摘要 &gt; 模型推测，那么在窗口不够的时候，就应该优先保留高可信信息，压缩或丢弃低可信信息。</p></li><li><p>信息新鲜度：新旧信息冲突时，新信息通常更重要，也就是你可以优先考虑压缩、丢弃一些旧信息。但是有一些例外，比如说用户画像这种，它虽然是一个老信息，但是它重要性非常高，你可千万别一冲动压缩或者丢弃了。</p></li><li><p>工具调用需求：如果当前步骤要选工具，就要放工具描述，但是工具描述本身是可以考虑压缩的。但我从体感上来说，一般压缩都会严重影响工具选择的准确率，慎用。</p></li><li><p>窗口充足：工具名、适用场景、不适用场景、参数说明、失败处理、few-shot</p></li><li><p>窗口中等：工具名、适用场景、核心参数</p></li><li><p>窗口紧张：工具名、一句话用途、关键禁用条件</p></li><li><p>few-shot 的动态策略：few-shot 很有用，但也很占 Token，所以也可以考虑动态放。</p></li><li><p>失败历史：如果某类任务过去经常因为某类 Context 缺失而失败，那么以后就应该提高这类 Context 的优先级。</p></li></ul><h3 id="动态编排决策表-供参考" tabindex="-1">动态编排决策表（供参考） <a class="header-anchor" href="#动态编排决策表-供参考" aria-label="Permalink to &quot;动态编排决策表（供参考）&quot;">​</a></h3><p>Context 类型</p><ul><li>窗口充足窗口中等窗口紧张极度紧张</li></ul><p>当前用户输入</p><ul><li>原文原文原文原文</li></ul><p>Goal</p><ul><li>完整结构化完整结构化简化结构化一句话</li></ul><p>你可以引入更加多的级别，也可以设计自己的不同策略。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>想必到现在，不管内容有没有彻底理解，但是你至少知道了一件事：传给大模型的内容是一个非常动态的东西。而且面试要想脱颖而出，最简单的办法就是设计一个自己的动态策略，然后用一个完整的故事，解释在不同的情况下，你这个动态策略是如何运作的。</p><p>前面我们聊的是在面试中比较能赢得亮点的方案。而在实践中，这种非常动态的策略性价比就不那么高了，实现起来比较费劲，最终效果提升也不是非常显著。而解决窗口大小不足的最佳办法，就是换一个窗口更大的大模型。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>假设你正在设计一个面试项目包装 Agent。用户已经和 Agent 连续对话了 30 轮，现在用户输入：</p><ul><li>“就按刚才那个 IM 中台方案继续写，但要更像高级后端项目，别太假，尤其不要编我没做过的数据。最后顺便给我生成 5 个面试官可能追问的问题。”</li></ul><p>当前任务阶段是：生成最终项目经历 + 面试追问。</p><p>模型最大上下文窗口是 32K Token，但是已经用了：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>System Prompt / Agent Spec：4K</span></span>
<span class="line"><span>安全规则与输出格式要求：2K</span></span>
<span class="line"><span>预计最终输出：8K</span></span>
<span class="line"><span>运行时 buffer：1K</span></span></code></pre></div><p>所以真正留给业务 Context 的空间只有 17K。而后你还有这些内容要考虑放进去：</p><p>问题：你传递给大模型的窗口内包含什么内容？你需要从两个角度回答：</p><ul><li><p>你会怎么决定哪些 Context 原样放入、哪些压缩、哪些只放索引、哪些不放？</p></li><li><p>顺序如何？谁在前谁在后，为什么？在这个顺序之下，你觉得缓存命中占比（缓存命中前缀长度 / 总长度）大概是多少？</p></li></ul><p>欢迎你把你的思路分享到留言区和我一起交流讨论，如果你觉得这节课的内容对你有所帮助，也欢迎你分享给需要的朋友，我们下节课再见！</p>`,137)])])}const d=a(t,[["render",p]]);export{k as __pageData,d as default};
